exercise.solution:
router.beforeEach(async (to) => {
  await useLessonsStore().ensureLoaded()
  const progress = useProgressStore()
  const moduleId = typeof to.params?.module === 'string' && typeof to.meta.track === 'string'
    ? useLessonsStore().findModule(to.meta.track, to.params.module)?.id
    : undefined
  if ((moduleId && progress.isModuleLocked(moduleId)) || (to.name === 'capstone' && !progress.capstoneUnlocked)) {
    return { name: 'dashboard', query: { blocked: moduleId ?? 'capstone' } }
  }
  return true
})
